(()=>{function clean(){document.querySelectorAll('.product-info>.eyebrow').forEach(el=>el.remove());document.querySelectorAll('.product-card .type').forEach(el=>el.remove());document.querySelectorAll('.product-info .detail-type').forEach(el=>{const t=el.textContent.trim();const m=t.match(/(\d+(?:\.\d+)?\s*(?:ml|مل|g|kg|gm|جرام|غرام|قطعة|pcs?))/i);if(m)el.textContent=m[1].replace(/\s+/g,' ');else{const parts=t.split('·').map(x=>x.trim()).filter(Boolean);if(parts.length>1)el.textContent=parts[parts.length-1]}})}function loadBurnerPrice(){if(document.querySelector('script[data-burner-price]'))return;const s=document.createElement('script');s.src='/burner-price-fix.js?v=200';s.defer=true;s.dataset.burnerPrice='1';document.head.appendChild(s)}function perfumeExtras(){const params=new URLSearchParams(window.location.search);if(params.get('collection')!=='perfume'||!/\/shop\/?$/.test(window.location.pathname))return;if(!document.getElementById('perfume-collection-banners')){const s=document.createElement('script');s.src='/perfume-collection-banners.js?v=20260930-restore2';s.defer=true;document.head.appendChild(s)}const addAyla=()=>{if(document.getElementById('perfume-bottom-banner'))return;const catalog=document.getElementById('collection');if(!catalog)return;const section=document.createElement('section');section.id='perfume-bottom-banner';section.className='ayla-bottom-banner';section.setAttribute('aria-label','Ayla — Best Seller');section.innerHTML='<a href="/products/ayla/" aria-label="Discover Ayla"><img src="/assets/WhatsApp%20Image%202026-09-21%20at%2016.11.33.jpeg" alt="Ayla — Sultana Perfumes" loading="lazy"></a>';catalog.insertAdjacentElement('afterend',section);if(!document.getElementById('ayla-bottom-banner-style')){const st=document.createElement('style');st.id='ayla-bottom-banner-style';st.textContent='.ayla-bottom-banner{display:block!important;width:100%;aspect-ratio:3/1;overflow:hidden;background:#eadbc0;margin:0}.ayla-bottom-banner a{display:block;width:100%;height:100%;overflow:hidden}.ayla-bottom-banner img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .9s cubic-bezier(.2,.75,.25,1),filter .55s ease}.ayla-bottom-banner a:hover img{transform:scale(1.025);filter:brightness(1.04)}@media(max-width:850px){.ayla-bottom-banner{aspect-ratio:3/1}.ayla-bottom-banner img{object-fit:cover}}@media(prefers-reduced-motion:reduce){.ayla-bottom-banner img{transition:none}}';document.head.appendChild(st)}};addAyla();setTimeout(addAyla,500);setTimeout(addAyla,1500)}function init(){clean();loadBurnerPrice();perfumeExtras()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();window.addEventListener('load',init);setTimeout(clean,300);setTimeout(clean,1200)})();